if (!payrollRunId || !jobObject || !jobObject.jobId) {
    console.error("Cannot cache job: Missing Run ID or Job ID.");
    return;
}

if (!this._jobsCache[payrollRunId]) {
    this._jobsCache[payrollRunId] = { jobs: {} };
}

const jobId = jobObject.jobId;
const existingData = this._jobsCache[payrollRunId].jobs[jobId] || {};

this._jobsCache[payrollRunId].jobs[jobId] = {
    ...existingData,
    ...jobObject
};

const shortJobId = jobId.split('-').at(0);

if (jobObject.status === "COMPLETED") {
    this.utils.toast(`Review ready (Job: ${shortJobId})`, "INFO");
} else if (jobObject.status === "FAILED") {
    this.utils.toast(`Review generation failed (Job: ${shortJobId})`, "ERROR");
}

if (!payrollRunId) throw new Error("Payroll Run ID is required.");

const response = await this.payrollAppApi.lonti_app_payroll_service_payroll_run_InitiateReviewPayrollRun(
    {
        id: payrollRunId,
        maskSensitiveWorkerInfo: false,
        encashAccrualBalances
    },
    {},
    {
        headers: {
            "X-Authorization": this.$cookies.get("id_token")
        }
    }
);

const jobData = response?.data?.PayrollRunReviewJob;
if (!jobData) throw new Error("Unexpected response: Job data missing.");

jobData.encashAccrualBalances = encashAccrualBalances;

return jobData;

const jobsMap = this.getCachedJobs(payrollRunId);
if (!jobsMap) return;

let prunedCount = 0;
const now = new Date();

Object.keys(jobsMap).forEach(jobId => {
    const job = jobsMap[jobId];
    if (job.expiresAt && new Date(job.expiresAt) < now) {
        delete jobsMap[jobId];
        prunedCount++;
    }
});

if (prunedCount > 0) {
    console.log(`Pruned ${prunedCount} expired jobs for run ${payrollRunId}`);
}

try {
    const response = await this.payrollAppApi.lonti_app_payroll_service_payroll_run_GetCachedPayrollRunReviewJob(
        { id: payrollRunId, jobId: jobId },
        { headers: {
            "X-Authorization": this.$cookies.get("id_token")
        } }
    );

    const jobData = response?.data?.PayrollRunReviewJob;

    if (jobData) {
        this.cacheJobDetails(payrollRunId, jobData);
        return true;
    }
    return false;
} catch (error) {
    console.warn(`Failed to refresh job ${jobId}`, error);
    return false;
}
